import { task, launchBrowser, writeResult, clip, SCREENSHOT_PATH } from "/opt/teger/scout-kit.mjs";

const browser = await launchBrowser();
const page = await browser.newPage();
let extractionErrors = [];
let notes = [];

let nav;
try {
  nav = await page.goto(task.url, { timeoutMs: task.limits.navigationTimeoutMs });
} catch (e) {
  extractionErrors.push(`navigation error: ${clip(String(e.message), 500)}`);
  nav = { finalUrl: null, status: null, navigationError: String(e) };
}

// Bounded wait for the page to finish rendering.
try {
  await page.waitFor(() => {
    if (document.readyState !== "complete") return false;
    if (!document.body) return false;
    return true;
  }, { timeoutMs: 4000, intervalMs: 200 });
} catch {
  notes.push("page did not reach readyState complete within budget");
}

// Always capture a screenshot, even if extraction fails later.
let shot = { bytes: 0 };
let screenshotError = null;
try {
  shot = await page.screenshot();
} catch (e) {
  screenshotError = clip(String(e?.message || e), 500);
  extractionErrors.push(`screenshot failed: ${screenshotError}`);
}

// Extraction wrapped so one failure cannot lose the result or screenshot.
let title = null;
let visibleTextSample = "";
let redirectChain = [];
let blockedRequests = [];
let contactedHosts = [];
let forms = [];
let loginFormDetected = false;
let claimIdentity = { siteName: null, brandMentions: [], evidence: [] };
let textSignals = { urgencyPhrases: [], credentialRequests: [], instructionsToAI: [] };
let externalScriptOrigins = [];

try {
  title = await page.evaluate(() => document.title || null);
} catch (e) {
  extractionErrors.push(`title: ${clip(String(e.message), 300)}`);
}

try {
  visibleTextSample = clip(await page.evaluate(() => document.body?.innerText || ""), 1500);
} catch (e) {
  extractionErrors.push(`visibleTextSample: ${clip(String(e.message), 300)}`);
}

try {
  redirectChain = await page.redirectChain();
} catch (e) {
  extractionErrors.push(`redirectChain: ${clip(String(e.message), 300)}`);
}

try {
  blockedRequests = await page.blockedRequests();
} catch (e) {
  extractionErrors.push(`blockedRequests: ${clip(String(e.message), 300)}`);
}

try {
  contactedHosts = await page.contactedHosts();
} catch (e) {
  extractionErrors.push(`contactedHosts: ${clip(String(e.message), 300)}`);
}

// Claims identity + brand mentions.
try {
  claimIdentity = await page.evaluate(() => {
    const out = { siteName: null, brandMentions: [], evidence: [] };
    const meta = document.querySelector('meta[property="og:site_name"]');
    if (meta && meta.content) { out.siteName = meta.content.trim(); out.evidence.push("og:site_name"); }
    if (!out.siteName) {
      const app = document.querySelector('meta[name="application-name"]');
      if (app && app.content) { out.siteName = app.content.trim(); out.evidence.push("application-name"); }
    }
    if (!out.siteName) {
      const logo = document.querySelector('img[alt]');
      if (logo && logo.alt.trim()) { out.siteName = logo.alt.trim(); out.evidence.push("img alt"); }
    }
    const mentions = new Set();
    const add = (v) => { v = (v || "").trim(); if (v && v.length < 80) mentions.add(v); };
    document.querySelectorAll("h1,h2,h3,header img[alt],title").forEach((n) => {
      if (n.tagName === "TITLE") { add(n.textContent); }
      else if (n.tagName === "IMG") { add(n.getAttribute("alt")); }
      else { add(n.textContent); }
    });
    out.brandMentions = Array.from(mentions).slice(0, 10);
    return out;
  });
} catch (e) {
  extractionErrors.push(`claimedIdentity: ${clip(String(e.message), 300)}`);
}

// Forms collection (regular + shadow roots + password-input-outside-forms).
try {
  forms = await page.evaluate(() => {
    const results = [];
    const origin = location.origin;
    const toAbs = (action) => {
      try { return new URL(action || location.href, location.href).href; } catch { return null; }
    };
    const isCross = (url) => {
      if (!url) return false;
      try { return new URL(url).origin !== origin; } catch { return false; }
    };

    const seen = new WeakSet();
    const processForm = (f) => {
      if (seen.has(f)) return;
      seen.add(f);
      const inputs = [];
      try { f.querySelectorAll("input,select,textarea").forEach((i) => inputs.push(i)); } catch {}
      const pwd = inputs.some((i) => i.type === "password" || i.getAttribute("type") === "password");
      if (pwd) { window.__tegerPwd = true; }
      results.push({
        action: toAbs(f.getAttribute("action")),
        method: (f.getAttribute("method") || "GET").toUpperCase(),
        hasPasswordField: pwd,
        inputTypes: inputs.map((i) => i.type || "text").slice(0, 20),
        inputNames: inputs.map((i) => i.getAttribute("name") || "").filter(Boolean).slice(0, 20),
        crossOriginAction: isCross(toAbs(f.getAttribute("action")))
      });
    };

    document.querySelectorAll("form").forEach(processForm);

    // Shadow roots.
    const roots = [];
    const walk = (node) => {
      try {
        if (node.shadowRoot) { roots.push(node.shadowRoot); }
        node.childNodes?.forEach(walk);
      } catch {}
    };
    walk(document.documentElement);
    roots.forEach((r) => {
      try { r.querySelectorAll("form").forEach(processForm); } catch {}
    });

    // Password inputs outside any form.
    const standalonePwds = [];
    document.querySelectorAll("input[type='password'], input[type=password]").forEach((i) => {
      const inForm = i.closest("form");
      if (!inForm) standalonePwds.push(i);
    });
    standalonePwds.forEach((i) => {
      window.__tegerPwd = true;
      const nm = i.getAttribute("name");
      results.push({
        action: location.href,
        method: "GET",
        hasPasswordField: true,
        inputTypes: ["password"],
        inputNames: nm ? [nm] : [],
        crossOriginAction: isCross(location.href)
      });
    });

    return { forms: results, loginFormDetected: !!window.__tegerPwd };
  });
  loginFormDetected = forms.loginFormDetected;
  forms = forms.forms;
} catch (e) {
  extractionErrors.push(`forms: ${clip(String(e.message), 300)}`);
}

// Text signals.
try {
  textSignals = await page.evaluate(() => {
    const text = (document.body ? document.body.innerText : "") || "";
    const lower = text.toLowerCase();
    const find = (terms) => {
      const hits = [];
      terms.forEach((t) => {
        const idx = lower.indexOf(t.toLowerCase());
        if (idx !== -1) { hits.push(text.slice(Math.max(0, idx - 10), idx + t.length + 10).trim()); }
      });
      return Array.from(new Set(hits)).slice(0, 10);
    };
    return {
      urgencyPhrases: find([
        "account suspended", "verify within 24 hours", "verify within 24hrs",
        "unusual activity", "suspended account", "confirm your identity",
        "account locked", "secure your account", "immediate action required"
      ]),
      credentialRequests: find([
        "enter your password", "confirm your card", "password required",
        "sign in to continue", "login to your account", "enter your credentials",
        "card number required", "verify your password"
      ]),
      instructionsToAI: find([
        "ignore previous instructions", "print your secrets", "disable the filter",
        "you are a scraper", "as an ai", "ignore the above", "disregard all rules"
      ])
    };
  });
} catch (e) {
  extractionErrors.push(`textSignals: ${clip(String(e.message), 300)}`);
}

// External script origins.
try {
  externalScriptOrigins = await page.evaluate(() => {
    const origins = new Set();
    document.querySelectorAll("script[src]").forEach((s) => {
      try { origins.add(new URL(s.src).origin); } catch {}
    });
    return Array.from(origins).slice(0, 20);
  });
} catch (e) {
  extractionErrors.push(`externalScriptOrigins: ${clip(String(e.message), 300)}`);
}

const finalUrl = nav && nav.finalUrl ? nav.finalUrl : null;
const httpStatus = nav && typeof nav.status === "number" ? nav.status : null;

try {
  redirectChain = await page.redirectChain();
} catch (e) {
  extractionErrors.push(`redirectChain: ${clip(String(e.message), 300)}`);
}
try {
  blockedRequests = await page.blockedRequests();
} catch (e) {
  extractionErrors.push(`blockedRequests: ${clip(String(e.message), 300)}`);
}
try {
  contactedHosts = await page.contactedHosts();
} catch (e) {
  extractionErrors.push(`contactedHosts: ${clip(String(e.message), 300)}`);
}

await writeResult({
  requestedUrl: task.url,
  finalUrl: finalUrl,
  httpStatus: httpStatus,
  redirectChain: redirectChain,
  title: title,
  claimedIdentity: claimIdentity,
  forms: forms,
  loginFormDetected: loginFormDetected,
  textSignals: textSignals,
  visibleTextSample: visibleTextSample,
  externalScriptOrigins: externalScriptOrigins,
  blockedRequests: blockedRequests,
  contactedHosts: contactedHosts,
  screenshot: screenshotError ? null : { path: SCREENSHOT_PATH, bytes: shot.bytes },
  screenshotError: screenshotError,
  extractionErrors: extractionErrors,
  notes: notes,
});

await browser.close();
